import{_ as e,o as l,c as a,a2 as d}from"./chunks/framework.CBxkvBm_.js";const f=JSON.parse('{"title":"Polyglot Language Ecosystem","description":"","frontmatter":{},"headers":[],"relativePath":"languages/overview.md","filePath":"languages/overview.md"}'),s={name:"languages/overview.md"};function o(i,t,n,r,c,g){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="polyglot-language-ecosystem" tabindex="-1">Polyglot Language Ecosystem <a class="header-anchor" href="#polyglot-language-ecosystem" aria-label="Permalink to &quot;Polyglot Language Ecosystem&quot;">​</a></h1><p>ModelScript is not a single-language compiler—it is a <strong>polyglot systems engineering framework</strong>. All engineering languages share the same WebAssembly GLR parser compiler (<code>@modelscript/dsl</code>), the same <code>SymbolIndex</code> and <code>WorkspaceIndex</code> architecture, and the same Triple Graph Grammar (TGG) synchronization engine.</p><hr><h2 id="supported-engineering-languages" tabindex="-1">Supported Engineering Languages <a class="header-anchor" href="#supported-engineering-languages" aria-label="Permalink to &quot;Supported Engineering Languages&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Language</th><th style="text-align:left;">Package</th><th style="text-align:left;">Extensions</th><th style="text-align:left;">Engineering Domain</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./modelica.html">Modelica 3.x</a></strong></td><td style="text-align:left;"><code>@modelscript/modelica</code></td><td style="text-align:left;"><code>.mo</code></td><td style="text-align:left;">Multi-domain acausal physical modeling &amp; DAE simulation</td></tr><tr><td style="text-align:left;"><strong><a href="./sysml2.html">SysML v2 &amp; KerML</a></strong></td><td style="text-align:left;"><code>@modelscript/sysml2</code></td><td style="text-align:left;"><code>.sysml, .sysml2, .kerml</code></td><td style="text-align:left;">Systems architecture, requirements, state machines &amp; verification</td></tr><tr><td style="text-align:left;"><strong><a href="./simulink.html">MATLAB Simulink</a></strong></td><td style="text-align:left;"><code>@modelscript/simulink</code></td><td style="text-align:left;"><code>.slx, .mdl</code></td><td style="text-align:left;">Continuous/discrete control block diagrams &amp; state-space transfer functions</td></tr><tr><td style="text-align:left;"><strong><a href="./autosar.html">AUTOSAR</a></strong></td><td style="text-align:left;"><code>@modelscript/autosar</code></td><td style="text-align:left;"><code>.arxml</code></td><td style="text-align:left;">Automotive Classic &amp; Adaptive ECU architectures &amp; Virtual RTE scheduling</td></tr><tr><td style="text-align:left;"><strong><a href="./reqif.html">ReqIF Requirements</a></strong></td><td style="text-align:left;"><code>@modelscript/reqif</code></td><td style="text-align:left;"><code>.reqif, .reqifz</code></td><td style="text-align:left;">Computable digital contracts &amp; Nelson-Oppen formal entailment verification</td></tr><tr><td style="text-align:left;"><strong><a href="./spice.html">SPICE Electronics</a></strong></td><td style="text-align:left;"><code>@modelscript/spice</code></td><td style="text-align:left;"><code>.cir, .sp, .net, .lib</code></td><td style="text-align:left;">Analog circuit netlists, OP, TRAN, AC frequency sweeps &amp; ECAD graph generation</td></tr><tr><td style="text-align:left;"><strong><a href="./simpack.html">SIMPACK MBD</a></strong></td><td style="text-align:left;"><code>@modelscript/simpack</code></td><td style="text-align:left;"><code>.spck, .sim, .mbs</code></td><td style="text-align:left;">High-frequency multibody dynamics, spatial joints &amp; flexible body synthesis</td></tr><tr><td style="text-align:left;"><strong><a href="./gensys.html">GENSYS Railway</a></strong></td><td style="text-align:left;"><code>@modelscript/gensys</code></td><td style="text-align:left;"><code>.calc, .geom, .track</code></td><td style="text-align:left;">Railway vehicle dynamics, FASTSIM wheel-rail contact &amp; EN 14363 homologation</td></tr><tr><td style="text-align:left;"><strong><a href="./adams.html">MSC Adams</a></strong></td><td style="text-align:left;"><code>@modelscript/adams</code></td><td style="text-align:left;"><code>.adm, .cmd</code></td><td style="text-align:left;">Mechanical system dynamics, 3D kinematic joints &amp; Grübler mobility analysis</td></tr><tr><td style="text-align:left;"><strong><a href="./urdf.html">URDF Robotics</a></strong></td><td style="text-align:left;"><code>@modelscript/urdf</code></td><td style="text-align:left;"><code>.urdf, .xacro</code></td><td style="text-align:left;">Robot kinematic trees, joint limits &amp; Featherstone recursive dynamics (ABA/RNEA)</td></tr><tr><td style="text-align:left;"><strong><a href="./pscad.html">PSCAD / EMT</a></strong></td><td style="text-align:left;"><code>@modelscript/pscad</code></td><td style="text-align:left;"><code>.pscx, .pslx, .pswx, .psmx, .cfg, .dat</code></td><td style="text-align:left;">Electromagnetic transients, power networks &amp; IEEE 2800 ride-through compliance</td></tr><tr><td style="text-align:left;"><strong><a href="./psse.html">PSS/E Power Flow</a></strong></td><td style="text-align:left;"><code>@modelscript/psse</code></td><td style="text-align:left;"><code>.raw, .dyr, .con</code></td><td style="text-align:left;">Large-scale power transmission grid power flow &amp; dynamic stability</td></tr><tr><td style="text-align:left;"><strong><a href="./olga.html">OLGA Multiphase</a></strong></td><td style="text-align:left;"><code>@modelscript/olga</code></td><td style="text-align:left;"><code>.opi, .key, .genkey, .tab</code></td><td style="text-align:left;">High-fidelity transient multiphase dynamic flow assurance &amp; slug tracking</td></tr><tr><td style="text-align:left;"><strong><a href="./lps.html">PipelineStudio</a></strong></td><td style="text-align:left;"><code>@modelscript/lps</code></td><td style="text-align:left;"><code>.lps, .tgx, .tlx, .tgn, .tln</code></td><td style="text-align:left;">Gas &amp; liquid pipeline transmission, line pack, batch tracking &amp; surge</td></tr><tr><td style="text-align:left;"><strong><a href="./easy5.html">EASY5</a></strong></td><td style="text-align:left;"><code>@modelscript/easy5</code></td><td style="text-align:left;"><code>.ez5, .ezm, .ezd, .eas, .tab</code></td><td style="text-align:left;">Classical &amp; modern dynamic simulation, linear state space analysis &amp; trim</td></tr><tr><td style="text-align:left;"><strong><a href="./gtsuite.html">GT-SUITE</a></strong></td><td style="text-align:left;"><code>@modelscript/gtsuite</code></td><td style="text-align:left;"><code>.gtm, .gtd, .gtx, .gt</code></td><td style="text-align:left;">1D powertrain, engine combustion, turbocharging &amp; thermo-fluids</td></tr><tr><td style="text-align:left;"><strong><a href="./sima.html">SIMA (SIMO / RIFLEX)</a></strong></td><td style="text-align:left;"><code>@modelscript/sima</code></td><td style="text-align:left;"><code>.inp, .sima, .sys, .hyd</code></td><td style="text-align:left;">Marine hydrodynamics, station keeping, catenary mooring &amp; slender dynamics</td></tr><tr><td style="text-align:left;"><strong><a href="./rocets.html">ROCETS</a></strong></td><td style="text-align:left;"><code>@modelscript/rocets</code></td><td style="text-align:left;"><code>.roc, .deck, .map</code></td><td style="text-align:left;">Liquid rocket engine transient simulation, turbomachinery &amp; combustion balance</td></tr><tr><td style="text-align:left;"><strong><a href="./step.html">STEP (ISO 10303)</a></strong></td><td style="text-align:left;"><code>@modelscript/step</code></td><td style="text-align:left;"><code>.step, .stp, .p21</code></td><td style="text-align:left;">Mechanical CAD B-Rep geometry, assemblies &amp; kinematic joints</td></tr><tr><td style="text-align:left;"><strong><a href="./owl2.html">OWL2 Ontology</a></strong></td><td style="text-align:left;"><code>@modelscript/owl2</code></td><td style="text-align:left;"><code>.owl, .owl2, .ofn, .ttl</code></td><td style="text-align:left;">Formal knowledge graphs, DL reasoning &amp; SPARQL querying</td></tr><tr><td style="text-align:left;"><strong><a href="./scad.html">OpenSCAD</a></strong></td><td style="text-align:left;"><code>@modelscript/scad</code></td><td style="text-align:left;"><code>.scad</code></td><td style="text-align:left;">Parametric Constructive Solid Geometry (CSG)</td></tr><tr><td style="text-align:left;"><strong><a href="./ssp.html">SSP 1.0 / 2.0</a></strong></td><td style="text-align:left;"><code>@modelscript/ssp</code></td><td style="text-align:left;"><code>.ssp, .ssd, .ssv</code></td><td style="text-align:left;">Co-Simulation System Structure &amp; Parameterization</td></tr><tr><td style="text-align:left;"><strong><a href="./cfd.html">CFD (SU2 &amp; OpenFOAM)</a></strong></td><td style="text-align:left;"><code>@modelscript/cfd</code></td><td style="text-align:left;"><code>.cfd, .cfg, .cfgt, .su2</code></td><td style="text-align:left;">Computational Fluid Dynamics solver configuration &amp; boundary markers</td></tr><tr><td style="text-align:left;"><strong><a href="./fea.html">FEA Structural</a></strong></td><td style="text-align:left;"><code>@modelscript/fea</code></td><td style="text-align:left;"><code>.fea, .inp, .inpt, .bdf</code></td><td style="text-align:left;">CalculiX / Abaqus (<code>.inp</code>, <code>.inpt</code>) &amp; NASTRAN (<code>.bdf</code>) structural mechanics</td></tr><tr><td style="text-align:left;"><strong><a href="./csv.html">CSV Telemetry</a></strong></td><td style="text-align:left;"><code>@modelscript/csv</code></td><td style="text-align:left;"><code>.csv</code></td><td style="text-align:left;">Tabular empirical measurement series &amp; lookup tables</td></tr><tr><td style="text-align:left;"><strong><a href="./modelscript.html">ModelScript</a></strong></td><td style="text-align:left;"><code>@modelscript/modelscript</code></td><td style="text-align:left;"><code>.msx, .modelscript</code></td><td style="text-align:left;">Native systems scripting, <code>@unmanaged struct</code> WASM/C++ kernels &amp; FLWOR queries</td></tr></tbody></table><hr><h2 id="unified-polyglot-pipeline" tabindex="-1">Unified Polyglot Pipeline <a class="header-anchor" href="#unified-polyglot-pipeline" aria-label="Permalink to &quot;Unified Polyglot Pipeline&quot;">​</a></h2><p>Every language plugin implements the <code>LanguageDefinition</code> interface (<code>packages/dsl/src/language.ts</code>):</p><ol><li><strong>Grammar DSL (<code>defineGrammar</code>)</strong>: Compiled Ahead-of-Time into a compact <code>.wasm</code> binary parser table.</li><li><strong>Symbol Indexer (<code>SymbolIndexer</code>)</strong>: Walks the linear-memory CST and populates <code>SymbolEntry</code> declarations into the global <code>WorkspaceIndex</code>.</li><li><strong>Salsa Queries (<code>queries</code>)</strong>: Memoized semantic analyses (type resolution, unit inference, structural validation).</li><li><strong>Compiler Lints (<code>lints</code>)</strong>: Real-time diagnostics surfaced identically in the CLI (<code>msx lint</code>), LSP server, and Web IDE.</li><li><strong>TGG Rules (<code>tggRules</code>)</strong>: Declarative bidirectional synchronization rules linking AST nodes across languages (e.g., <code>SysMLv2 PartUsage</code> $\\leftrightarrow$ <code>Modelica Component</code> $\\leftrightarrow$ <code>STEP Product</code> $\\leftrightarrow$ <code>ModelScript Struct</code>).</li></ol>',9)])])}const y=e(s,[["render",o]]);export{f as __pageData,y as default};
